ALTER TABLE public.investigations ADD COLUMN IF NOT EXISTS revision integer NOT NULL DEFAULT 0;
ALTER TABLE public.investigations ADD COLUMN IF NOT EXISTS lease_id uuid;
ALTER TABLE public.investigations ADD COLUMN IF NOT EXISTS lease_until timestamptz;
ALTER TABLE public.investigations ADD COLUMN IF NOT EXISTS expires_at timestamptz;
CREATE INDEX IF NOT EXISTS investigations_expiry ON public.investigations(expires_at) WHERE expires_at IS NOT NULL;
CREATE TABLE public.recon_preferences (user_id uuid PRIMARY KEY DEFAULT auth.uid(), retention_days integer, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.recon_preferences TO authenticated;
GRANT ALL ON public.recon_preferences TO service_role;
ALTER TABLE public.recon_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner preferences" ON public.recon_preferences FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.recon_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), investigation_id uuid NOT NULL REFERENCES public.investigations(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'followup', question text NOT NULL DEFAULT '', content jsonb NOT NULL DEFAULT '{}'::jsonb, comparison_id uuid REFERENCES public.investigations(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.recon_artifacts TO authenticated;
GRANT ALL ON public.recon_artifacts TO service_role;
ALTER TABLE public.recon_artifacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner artifact read" ON public.recon_artifacts FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Owner artifact insert" ON public.recon_artifacts FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.investigations i WHERE i.id = investigation_id AND i.user_id = auth.uid()) AND (comparison_id IS NULL OR EXISTS (SELECT 1 FROM public.investigations i WHERE i.id = comparison_id AND i.user_id = auth.uid())));
CREATE POLICY "Owner artifact delete" ON public.recon_artifacts FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.recon_claim(p_id uuid, p_lease uuid) RETURNS SETOF public.investigations LANGUAGE plpgsql SET search_path = public AS $$ BEGIN RETURN QUERY UPDATE public.investigations SET lease_id = p_lease, lease_until = now() + interval '3 minutes' WHERE id = p_id AND user_id = auth.uid() AND status IN ('queued','running') AND (lease_until IS NULL OR lease_until < now()) RETURNING *; END; $$;
REVOKE ALL ON FUNCTION public.recon_claim(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.recon_claim(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.recon_expiry() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ DECLARE days integer; BEGIN SELECT retention_days INTO days FROM public.recon_preferences WHERE user_id = NEW.user_id; IF days IS NOT NULL AND days NOT IN (7,30,90) THEN RAISE EXCEPTION 'Choose 7, 30, 90 days or keep until deleted'; END IF; NEW.expires_at := CASE WHEN days IS NULL THEN NULL ELSE now() + make_interval(days => days) END; RETURN NEW; END; $$;
CREATE TRIGGER recon_set_expiry BEFORE INSERT ON public.investigations FOR EACH ROW EXECUTE FUNCTION public.recon_expiry();
CREATE OR REPLACE FUNCTION public.recon_validate_preferences() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.retention_days IS NOT NULL AND NEW.retention_days NOT IN (7,30,90) THEN RAISE EXCEPTION 'Choose 7, 30, 90 days or keep until deleted'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER recon_preferences_valid BEFORE INSERT OR UPDATE ON public.recon_preferences FOR EACH ROW EXECUTE FUNCTION public.recon_validate_preferences();
REVOKE ALL ON public.user_secrets FROM anon, authenticated;
DROP POLICY IF EXISTS "Users manage their own secrets" ON public.user_secrets;
COMMENT ON TABLE public.user_secrets IS 'Server-only owner-scoped token storage; value stores versioned ciphertext after upgrade. Legacy plaintext is encrypted on authenticated access.';